macro_rules! FromRadix16 {
    () => {
        # [doc = " Types implementing this trait can be parsed from a positional numeral system with radix 16"] pub trait FromRadix16 : Sized { # [doc = " Parses an integer from a slice."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use atoi::FromRadix16;"] # [doc = " // Parsing to digits from a slice"] # [doc = " assert_eq!((42,2), u32::from_radix_16(b\"2a\"));"] # [doc = " // Additional bytes after the number are ignored"] # [doc = " assert_eq!((42,2), u32::from_radix_16(b\"2a is the answer to life, the universe and everything\"));"] # [doc = " // (0,0) is returned if the slice does not start with a digit"] # [doc = " assert_eq!((0,0), u32::from_radix_16(b\"Sadly we do not know the question\"));"] # [doc = " // While signed integer types are supported..."] # [doc = " assert_eq!((42,2), i32::from_radix_16(b\"2a\"));"] # [doc = " // Signs are not allowed (even for signed integer types)"] # [doc = " assert_eq!((0,0), i32::from_radix_16(b\"-2a\"));"] # [doc = " // Leading zeros are allowed"] # [doc = " assert_eq!((42,4), u32::from_radix_16(b\"002a\"));"] # [doc = " // so are uppercase letters"] # [doc = " assert_eq!((42,4), u32::from_radix_16(b\"002A\"));"] # [doc = " ```"] # [doc = ""] # [doc = " # Return"] # [doc = ""] # [doc = " Returns a tuple with two numbers. The first is the integer parsed or zero, the second is the"] # [doc = " index of the byte right after the parsed number. If the second element is zero the slice"] # [doc = " did not start with an ASCII digit."] fn from_radix_16 (_ : & [u8]) -> (Self , usize) ; }
    };
}

FromRadix16!();